package com.ecommerce.controller;
import com.ecommerce.dao.ProductDAO; import com.ecommerce.model.*; import com.ecommerce.util.View; import javax.servlet.*; import javax.servlet.annotation.WebServlet; import javax.servlet.http.*; import java.io.IOException; import java.math.BigDecimal; import java.util.*;
@WebServlet("/cart") public class CartServlet extends HttpServlet{
 private List<CartItem> cart(HttpSession s){List<CartItem> c=(List<CartItem>)s.getAttribute("cart");if(c==null){c=new ArrayList<>();s.setAttribute("cart",c);}return c;}
 protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{List<CartItem> c=cart(req.getSession());BigDecimal total=BigDecimal.ZERO;for(CartItem i:c)total=total.add(i.getSubtotal());req.setAttribute("cartTotal",total);View.forward(req,resp,"cart.jsp");}
 protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{try{String action=req.getParameter("action");List<CartItem> c=cart(req.getSession());int pid=Integer.parseInt(req.getParameter("productId")); if("remove".equals(action)){c.removeIf(x->x.getProduct().getId()==pid);} else {Product p=new ProductDAO().findById(pid);int qty=req.getParameter("quantity")==null?1:Integer.parseInt(req.getParameter("quantity")); if(qty<1)qty=1; Optional<CartItem> existing=c.stream().filter(x->x.getProduct().getId()==pid).findFirst(); if("update".equals(action)){int q=Math.min(qty,p.getStock()); if(existing.isPresent())existing.get().setQuantity(q);} else {if(p.getStock()>0){if(existing.isPresent())existing.get().setQuantity(Math.min(existing.get().getQuantity()+qty,p.getStock()));else c.add(new CartItem(p,Math.min(qty,p.getStock())));}}} resp.sendRedirect(req.getContextPath()+"/cart");}catch(Exception e){throw new ServletException(e);}}
}
